package org.eclipse.rdf4j.sail.lmdb.evaluation.fragment;

import java.util.concurrent.atomic.LongAdder;

/**
 * Process-wide fragment-tier counters. Physical and logical effects are tracked separately because factorized placement
 * misprices otherwise: 100 physical tests eliminating 10M logical rows is radically different from 100 tests
 * eliminating 100 rows. Counters are monotonically increasing and cheap ({@link LongAdder}); consumers snapshot and
 * diff.
 */
public final class FragmentTelemetry {

	private FragmentTelemetry() {
	}

	/** Fragment fast-path evaluations that decided TRUE/FALSE/ERROR without escaping. */
	public static final LongAdder FAST_PATH_DECISIONS = new LongAdder();
	/** Evaluations that escaped to the exact tier. */
	public static final LongAdder ESCAPES = new LongAdder();
	/** Physical values rejected by fragment fast paths. */
	public static final LongAdder PHYSICAL_REJECTIONS = new LongAdder();
	/** Logical multiplicity rejected (physical rejections weighted by factorized multiplicity). */
	public static final LongAdder LOGICAL_MULTIPLICITY_REJECTED = new LongAdder();
	/** Memo-form hits and misses. */
	public static final LongAdder MEMO_HITS = new LongAdder();
	public static final LongAdder MEMO_MISSES = new LongAdder();
	/** Fragment recognitions (a live engine filter admitted to the fragment fast path) and declines. */
	public static final LongAdder RECOGNIZED = new LongAdder();
	public static final LongAdder DECLINED = new LongAdder();

	/** Snapshot for tests and explain output. */
	public static long[] snapshot() {
		return new long[] { FAST_PATH_DECISIONS.sum(), ESCAPES.sum(), PHYSICAL_REJECTIONS.sum(),
				LOGICAL_MULTIPLICITY_REJECTED.sum(), MEMO_HITS.sum(), MEMO_MISSES.sum(), RECOGNIZED.sum(),
				DECLINED.sum() };
	}
}
